// MD3 Compliant - Block G Migration (6 violations eliminated)

import * as React from 'react';
import { useState } from 'react';
import { Studente, Valutazione } from '../types';
import { RATING_OPTIONS, EVALUATION_TYPES } from '../constants';
import { M3ChoiceCard, SelectField, TextField, TextArea, M3Button, M3Dialog, M3DialogContent, M3DialogActions, M3Typography } from './ui';
interface AddEvaluationModalProps {
    students: Studente[];
    discipline: string[];
    onClose: () => void;
    onSave: (evaluation: Omit<Valutazione, 'id'>) => void;
}

interface AddEvaluationModalProps {
    students: Studente[];
    discipline: string[];
    onClose: () => void;
    onSave: (evaluation: Omit<Valutazione, 'id'>) => void;
}

const getTestTypeIcon = (tipo: string) => {
  switch (tipo) {
        case 'Scritto': return 'edit_note';
        case 'Orale': return 'record_voice_over';
        case 'Pratico': return 'build';
        case 'Test': return 'quiz';
        case 'Verifica': return 'assignment_late';
        default: return 'assignment';
    }
};

const AddEvaluationModal: React.FC<AddEvaluationModalProps> = ({
    students,
    discipline,
    onClose,
    onSave
}: AddEvaluationModalProps) => {
    const [selectedStudentId, setSelectedStudentId] = useState<string>('');
    const [selectedMateria, setSelectedMateria] = useState<string>(discipline[0] || '');
    const [tipo, setTipo] = useState<Valutazione['tipo]>('Orale');
    const [voto, setVoto] = useState<string>('');
    const [argomento, setArgomento] = useState<string>('');
    const [note, setNote] = useState<string>('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedStudentId || !selectedMateria || !voto) {
            alert("Compila tutti i campi obbligatori (Studente, Materia, Voto).");
            return;
        }
        onSave({
            studenteId: selectedStudentId,
            materia: selectedMateria,
            data: new Date().toISOString(),
            tipo,
            voto,
            argomento,
            note,
        });
        onClose();
    };

    return (
        <M3Dialog
            title="Aggiungi Valutazione"
            onClose={onClose}
            maxWidth="sm"
            level={1}
        >
            <form onSubmit={handleSubmit} className="md3-eval-form">
                <M3DialogContent className="md3-eval-content">
                    <SelectField
                        id="eval-student-select"
                        label="Studente"
                        value={selectedStudentId}
                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setSelectedStudentId(e.target.value)}
                        required
                    >
                        <option value="">Seleziona studente...</option>
                        {students.map((s: Studente) => <option key={s.id} value={s.id}>{s.cognome} {s.nome}</option>)}
                    </SelectField>

                    <div className="md3-eval-grid">
                        <SelectField
                            id="eval-materia-select"
                            label="Materia"
                            value={selectedMateria}
                            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setSelectedMateria(e.target.value)}
                            required
                        >
                            <option value="">Seleziona...</option>
                            {discipline.map((d: string) => <option key={d} value={d}>{d}</option>)}
                        </SelectField>
                        <SelectField
                            id="eval-voto-select"
                            label="Voto / Giudizio"
                            value={voto}
                            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setVoto(e.target.value)}
                            required
                        >
                            <option value="">Seleziona...</option>
                            {RATING_OPTIONS.map((o: string) => <option key={o} value={o}>{o}</option>)}
                        </SelectField>
                    </div>

                    <div>
                        <M3Typography
                            variant="label-small"
                            className="md3-eval-type-label"
                        >
                            Tipo Prova
                        </M3Typography>
                        <div className="md3-eval-choice-container"
                        onScroll={(e) => {
                            // Hide scrollbar for webkit browsers
                            const target = e.target as HTMLElement;
                            target.style.setProperty('-webkit-scrollbar', 'none');
                        }}>
                            {EVALUATION_TYPES.map(t => (
                                <M3ChoiceCard
                                    key={t}
                                    icon={getTestTypeIcon(t)}
                                    label={t}
                                    onClick={() => setTipo(t)}
                                    selected={tipo === t}
                                />
                            ))}
                        </div>
                    </div>

                    <TextField
                        id="eval-argomento-input"
                        label="Argomento"
                        value={argomento}
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setArgomento(e.target.value)}
                        placeholder="Es. 'Il Barocco in Italia'"
                    />

                    <TextArea
                        id="eval-note-textarea"
                        label="Note Aggiuntive"
                        value={note}
                        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setNote(e.target.value)}
                        rows={2}
                    />
                </M3DialogContent>

                <M3DialogActions className="md3-eval-actions">
                    <M3Button variant="text" onClick={onClose} type="button">Annulla</M3Button>
                    <M3Button variant="filled" type="submit">Salva Valutazione</M3Button>
                </M3DialogActions>
            </form>
        </M3Dialog>
    );
};

export default AddEvaluationModal;

// LEGACY - MD3 Non-compliant

import React, { useState, useCallback } from 'react';
import { useFileDrop } from '../hooks/useFileDrop';
import { KnowledgeBaseEntry, Corpus } from '../types';
import { extractTextFromFile, blobToBase64Parts } from '../utils/documentUtils';
import { KB_CATEGORIES } from '../constants';
import { CategoryCard, SelectField, TextField, M3Dialog, M3DialogContent, M3Button } from './ui';
interface AddSourceModalProps {
    corpora: Corpus[];
    setCorpora: React.Dispatch<React.SetStateAction<Corpus[]>>;
    onClose: () => void;
    onAddEntries: (entries: KnowledgeBaseEntry[]) => void;
}

const AddSourceModal: React.FC<AddSourceModalProps> = ({ corpora, setCorpora, onClose, onAddEntries }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
    const [selectedCorpusId, setSelectedCorpusId] = useState<string>('');
    const [isCreating, setIsCreating] = useState(false);
    const [newCorpusName, setNewCorpusName] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [loadingMessage, setLoadingMessage] = useState('');
    const [error, setError] = useState('');

    const handleCreateCorpus = () => {
        if (!newCorpusName.trim()) return;
        const newCorpus: Corpus = { id: `corpus-${Date.now()}`, displayName: newCorpusName.trim(), chatHistory: [] };
        setCorpora(prev => [...prev, newCorpus]);
        setNewCorpusName('');
        setIsCreating(false);
        setSelectedCorpusId(newCorpus.id); 
    };

    const processFiles = async (files: File[]) => {
        if (!selectedCategory) { setError("Seleziona una cartella."); return; }
        setIsLoading(true);
        const newEntries: KnowledgeBaseEntry[] = [];
        for (const file of files) {
            try {
                setLoadingMessage(`Processo: ${file.name}`);
                const textContent = await extractTextFromFile(file);
                const fileData = await blobToBase64Parts(file);
                newEntries.push({ id: `kb-${Date.now()}-${file.name}`, fileName: file.name, content: textContent, fileContent: fileData, corpusId: selectedCorpusId || undefined, category: selectedCategory });
            } catch(e: unknown) {
                const errMsg = e instanceof Error ? e.message : String(e);
                setError(prev => `${prev}\n❌ ${file.name}: ${errMsg}`);
            }
        }
        if (newEntries.length > 0) onAddEntries(newEntries);
        setIsLoading(false);
        if (!error) onClose();
    };

    const onDrop = useCallback((acceptedFiles: File[]) => processFiles(acceptedFiles), [selectedCategory, selectedCorpusId, processFiles]);
    const { getRootProps, getInputProps, isDragActive } = useFileDrop({ onDrop, disabled: isLoading || !selectedCategory });

    return (
        <M3Dialog
            title="Aggiungi Documenti"
            onClose={onClose}
            maxWidth="sm"
            level={1}
        >
            <M3DialogContent style={{marginTop: 'var(--md-sys-spacing-8)'}}>
                {isLoading ? (
                    <div  style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                        <div  style={{borderRadius: 'var(--md-sys-spacing-4)', height: 'var(--md-sys-spacing-4)', width: 'var(--md-sys-spacing-4)', borderBottom: "4px solid var(--md-sys-color-outline)", borderColor: "var(--md-sys-color-primary)"}}></div>
                        <p  style={{color: "var(--md-sys-color-primary)", textTransform: "uppercase", letterSpacing: "0.1em"}}>{loadingMessage}</p>
                    </div>
                ) : (
                    <>
                        <section>
                            <h3  style={{marginBottom: 'var(--md-sys-spacing-6)', display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-6)'}}>
                                <span style={{ color: sys.colors.on-primaryContainer , width: 'var(--md-sys-spacing-4)', height: 'var(--md-sys-spacing-4)', borderRadius: 'var(--md-sys-spacing-4)', backgroundColor: "var(--md-sys-color-primary)", display: "flex", alignItems: "center", justifyContent: "center"}}>1</span> 
                                Seleziona Destinazione
                            </h3>
                            <div  style={{display: "grid", gridTemplateColumns: "1fr 1fr", gap: 'var(--md-sys-spacing-6)'}}>
                                {KB_CATEGORIES.map(cat => (
                                    <CategoryCard 
                                        key={cat.id} 
                                        id={cat.id} 
                                        label={cat.label} 
                                        icon={cat.icon} 
                                        color={cat.color} 
                                        isSelected={selectedCategory === cat.id} 
                                        onClick={() => setSelectedCategory(cat.id)} 
                                    />
                                ))}
                            </div>
                        </section>

                        <section className={`transition-all duration-500 ${!selectedCategory ? 'opacity-30 grayscale pointer-events-none' : ''}`}>
                            <h3  style={{marginBottom: 'var(--md-sys-spacing-6)', display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-6)'}}>
                                <span style={{ color: sys.colors.on-secondary-container , width: 'var(--md-sys-spacing-4)', height: 'var(--md-sys-spacing-4)', borderRadius: 'var(--md-sys-spacing-4)', backgroundColor: "var(--md-sys-color-secondary)", display: "flex", alignItems: "center", justifyContent: "center"}}>2</span> 
                                Carica File
                            </h3>
                            <div {...getRootProps()} className={`dropzone-area h-48 border-2 border-dashed ${isDragActive ? 'border-primary bg-primaryContainer/10 scale-[1.02]' : 'border-[var(--md-sys-color-outline-variant)]'} transition-all flex flex-col items-center justify-center cursor-pointer`} style={{borderRadius: 'var(--md-sys-shape-corner-extra)'}}>
                                <input {...getInputProps()} />
                                <span style={{color: "var(--md-sys-color-primary)", marginBottom: 'var(--md-sys-spacing-8)'}}>{isDragActive ? 'download' : 'upload_file'}</span>
                                <p style={{ color: "var(--md-sys-color-on-surface-variant)" }}>Trascina i file qui o clicca per sfogliare</p>
                                <p style={{opacity: "0.6", marginTop: 'var(--md-sys-spacing-4)', fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.1em", color: "var(--md-sys-color-on-surface-variant)"}}>Supporto PDF, DOCX, TXT</p>
                            </div>
                        </section>

                        <section  style={{borderTop: "1px solid var(--md-sys-color-outline)"}}>
                            <h3  style={{fontWeight: "900", marginBottom: 'var(--md-sys-spacing-6)', display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-6)'}}>
                                <span style={{ color: sys.colors.on-tertiary , width: 'var(--md-sys-spacing-4)', height: 'var(--md-sys-spacing-4)', borderRadius: 'var(--md-sys-spacing-4)', backgroundColor: "var(--md-sys-color-tertiary)", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: "900"}}>3</span> 
                                Raccolta (Opzionale)
                            </h3>
                            <div style={{display: "flex", gap: 'var(--md-sys-spacing-8)', alignItems: "flex-end"}}>
                                <div style={{ flexGrow: "1" }}>
                                    <SelectField id="corpus-select" label="Raccolta Target" value={selectedCorpusId} onChange={e => setSelectedCorpusId(e.target.value)}>
                                        <option value="">-- Nessuna Raccolta --</option>
                                        {corpora.map(c => <option key={c.id} value={c.id}>{c.displayName}</option>)}
                                    </SelectField>
                                </div>
                                <M3Button 
                                    onClick={() => setIsCreating(p => !p)} 
                                    variant="tonal"
                                     
                                    title={isCreating ? "Annulla creazione" : "Crea nuova raccolta"}
                                >
                                    <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>{isCreating ? 'remove' : 'add'}</span>
                                </M3Button>
                            </div>
                            {isCreating && (
                                 <div  style={{marginTop: 'var(--md-sys-spacing-6)', display: "flex", gap: 'var(--md-sys-spacing-6)'}}>
                                    <TextField 
                                        id="new-corpus-name-input" 
                                        label="Nome Nuova Raccolta" 
                                        value={newCorpusName} 
                                        onChange={e => setNewCorpusName(e.target.value)} 
                                        containerClassName="flex-grow !mb-0" 
                                        placeholder="Es. Programmazioni 2024" 
                                    />
                                    <M3Button onClick={handleCreateCorpus} variant="primary"  style={{ fontWeight: "900" }}>CREA</M3Button>
                                </div>
                            )}
                        </section>
                    </>
                )}
                {error && <div style={{ color: sys.colors.on-error-container , marginTop: 'var(--md-sys-spacing-4)', padding: 'var(--md-sys-spacing-6)', backgroundColor: "var(--md-sys-color-error)", borderRadius: "0.375rem"}}>{error}</div>}
            </M3DialogContent>
        </M3Dialog>
    );
};

export default AddSourceModal;

// LEGACY - MD3 Non-compliant

import React, { useState } from 'react';
import { AiSettings, Studente, TimetableSettings, Valutazione, ValutazioneCompetenza } from '../types';
import { getAIPedagogicalAdvice } from '../services/aiService';
import { AiThinkingGem } from './ui';

// M3Expressive: Refactored to use dedicated CSS classes with M3 tokens for AI advisor interface, form controls, and advice display
interface AiAdvisorProps {
    students: Studente[];
    evaluations: Valutazione[];
    competencyEvals: ValutazioneCompetenza[];
    settings: TimetableSettings;
    aiSettings: AiSettings;
}

interface Advice {
    titolo: string;
    descrizione: string;
}

const AiAdvisor: React.FC<AiAdvisorProps> = ({ students, evaluations, competencyEvals, settings, aiSettings }) => {
    const [advisorStatus, setAdvisorStatus] = useState<string | null>(null);
    const [advice, setAdvice] = useState<Advice[] | null>(null);
    const [error, setError] = useState('');
    const [selectedStudentId, setSelectedStudentId] = useState<string>('all');
    const [requestType, setRequestType] = useState<'recupero' | 'potenziamento'>('recupero');

    const handleGenerateAdvice = async () => {
        setAdvisorStatus("Analisi dei dati in corso...");
        setAdvice(null);
        setError('');

        try {
            let studentData: unknown;
            if (selectedStudentId === 'all') {
                studentData = {
                    nome: "Tutta la classe",
                    valutazioni: evaluations.slice(-30), // last 30 evals for the class
                    competenze: competencyEvals.slice(-30)
                };
            } else {
                const student = students.find(s => s.id === selectedStudentId);
                if (!student) throw new Error("Studente non trovato.");
                studentData = {
                    nome: `${student.cognome} ${student.nome}`,
                    valutazioni: evaluations.filter(e => e.studenteId === student.id),
                    competenze: competencyEvals.filter(e => e.studenteId === student.id)
                };
            }
            
            setAdvisorStatus(requestType === 'recupero' ? "Elaborazione strategie di recupero..." : "Elaborazione strategie di potenziamento...");
            await new Promise(r => setTimeout(r, 500)); // UX delay

            const result = await getAIPedagogicalAdvice(aiSettings, studentData, requestType, settings.competenze);
            setAdvice(result.suggerimenti);
        } catch (err) {
            const errorMsg = err instanceof Error ? err.message : "Si è verificato un errore durante la generazione del consiglio.";
            console.error(err);
            setError(errorMsg);
        } finally {
            setAdvisorStatus(null);
        }
    };

    return (
        <div >
            <h2 >
                <span >psychology</span>
                Consulente Didattico AI
            </h2>
            <p >
                Seleziona uno studente (o l'intera classe) e un obiettivo. L'AI analizzerà i dati e proporrà attività personalizzate.
            </p>

            <div >
                <div >
                    <label htmlFor="student-select-advisor" >Studente / Gruppo</label>
                    <select id="student-select-advisor" value={selectedStudentId} onChange={e => setSelectedStudentId(e.target.value)} >
                        <option value="all">Tutta la classe</option>
                        {students.map(s => <option key={s.id} value={s.id}>{s.cognome} {s.nome}</option>)}
                    </select>
                </div>
                <div >
                    <label >Tipo di Intervento</label>
                    <div >
                        <button type="button" onClick={() => setRequestType('recupero')} className={`ai-advisor-segmented-button ${requestType === 'recupero' ? 'active' : ''}`}>Recupero</button>
                        <button type="button" onClick={() => setRequestType('potenziamento')} className={`ai-advisor-segmented-button ${requestType === 'potenziamento' ? 'active' : ''}`}>Potenziamento</button>
                    </div>
                </div>
                 <div >
                    <button onClick={handleGenerateAdvice} disabled={!!advisorStatus} >
                        {advisorStatus ? <AiThinkingGem size="small" inline text="" /> : 'Genera Consiglio'}
                    </button>
                </div>
            </div>

            {advisorStatus && (
                 <div >
                    <AiThinkingGem size="medium" text={advisorStatus} />
                </div>
            )}
            {error && <p >{error}</p>}
            {advice && (
                <div >
                    <h3 >Suggerimenti dell'AI:</h3>
                    {advice.map((item, index) => (
                        <div key={index} >
                            <h4 >{item.titolo}</h4>
                            <p >{item.descrizione}</p>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default AiAdvisor;

import AssistantModal from './AssistantModal';
import '../font-setup';
import * as React from 'react';
import '../design-system/typography.css';
import '../design-system/spacing.css';
import '../design-system/breakpoints.css';
import '../design-system/accessibility-focus.css';

// Global runtime types are declared in `src/vite-env.d.ts`

import AssistantFab from './AssistantFab';
import { useAppEngine } from '../hooks/useAppEngine';
import { Header } from './Header';
import { SkipLink } from './accessibility/SkipLink';

import NavigationRail from './NavigationRail';
import ViewManager from './ViewManager';
import SignInScreen from './SignInScreen';
import { ModalManager } from './ModalManager';
import PassaggioAnnoWizard from './PassaggioAnnoWizard';

import { ThemeService } from '../services/ThemeService';
import { Z_INDEX } from '../design-system/zIndex';
import Snackbar from './Snackbar';
import { useRestoreAssist } from './useRestoreAssist';
import type { UserProfile, AiSuggestion, SystemSuggestion, KnowledgeBaseEntry, EventoCalendario } from '../types';
import ErrorBoundary from './ErrorBoundary';
type SuggestionBannerProps = { suggestion: AiSuggestion | SystemSuggestion; onAction: () => void };
// Banner Suggestion Assistant
const SuggestionBanner: React.FC<SuggestionBannerProps> = ({ suggestion, onAction }) => {
    // Support both AiSuggestion and SystemSuggestion
    const message = 'message' in suggestion ? suggestion.message : suggestion.description;
    const actionLabel = 'actionLabel' in suggestion ? suggestion.actionLabel : 'Apri';
    return (
        <div
             style={{
               paddingTop: 'var(--md-sys-spacing-4)',
               paddingBottom: 'var(--md-sys-spacing-4)',
               paddingLeft: 'var(--md-sys-spacing-4)',
               paddingRight: 'var(--md-sys-spacing-4)',
               display: "flex",
               alignItems: "center",
               justifyContent: "center",
               gap: 'var(--md-sys-spacing-4)', 
               cursor: "pointer", 
               borderBottom: "1px solid var(--md-sys-color-outline)", 
               zIndex: Z_INDEX.notification.banner
             }}
            onClick={onAction}
            role="button"
            aria-label={actionLabel || 'Apri suggerimento'}
        >
            <span style={{ fontSize: "1.25rem" }} aria-hidden="true">??</span>
            <span style={{ 
                color: 'var(--md-sys-color-on-primary-container)',
                fontWeight: "bold", 
                flex: "1", 
                fontSize: "0.875rem", 
                overflow: "hidden", 
                textOverflow: "ellipsis", 
                whiteSpace: "nowrap" 
            }}>
                {message || 'Hai un suggerimento!'}
            </span>
              <button  style={{fontSize: "0.75rem", display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-4)'}}>
                {actionLabel}
                <span  style={{ fontSize: "0.875rem" }}>north_east</span>
            </button>
        </div>
    );
};

import { useUIStore } from '../stores/useUIStore';
import { useModal } from '../context/ModalContext';
import HelpModal from './HelpModal';
import ImageAnalysisModal from './ImageAnalysisModal';
import OperationsCenter from './OperationsCenter';
import VideoAnalysisModal from './VideoAnalysisModal';
import CircolareAnalysisModal from './CircolareAnalysisModal';
import LoadingModal from './LoadingModal';
import { NKABottomSheet, useNKAStore } from '../nka';
import { useTheme } from '../theme/theme';

/**
 * App.tsx - Il core del Presentation Layer.
 * Gestisce l'App Shell e la sincronizzazione del tema.
 */
export const App: React.FC = () => {
    const { chaosStage } = useUIStore();
    const { pushModal, popModal } = useModal();
    // Stato assistant mode centralizzato (opzionale: puoi usare Zustand o context se vuoi cambiare modalit� da altri punti)
      const [assistantMode] = React.useState<'chat' | 'docs' | 'tools' | 'backup'>('chat');
    // AssistantModal montato una sola volta a livello root, usa solo modals proxy
    try {
        const result = useAppEngine();
        const { view, viewContext, appState, actions, modals } = result;

        // NOTE: removed previous dev-only forced-close effect because it interfered
        // with automated E2E flows (caused modal to be closed before tests could
        // interact). If you need a dev-only helper, enable it via an explicit
        // runtime flag (e.g. VITE_ENABLE_FORCE_CLOSE) rather than unconditionally
        // running on mount.
        const { user, themeState, aiSettings, isGlobalAiLoading, notifiche, activeSuggestion, installPrompt } = appState;

        // Sync Loading Modal with ModalProvider
        React.useEffect(() => {
            if (modals.isLoadingModalOpen) {
                pushModal({
                    id: 'loading-modal',
                    component: <LoadingModal message={modals.loadingModalMessage ?? 'Caricamento...'} />
                });
            } else {
                popModal('loading-modal');
            }
}, [modals.isLoadingModalOpen, modals.loadingModalMessage, pushModal, popModal]);

        // Runtime instrumentation for automated tests and diagnostics
        React.useEffect(() => {
            try {
                window.__app_instrumentation = window.__app_instrumentation || {};
                window.__app_instrumentation.user = user ? { id: user.id, displayName: (user as { id: string; displayName?: string }).displayName } : undefined;
                  console.info('[instrument] user', window.__app_instrumentation.user);
            } catch {
                /* ignore */
            }
}, [user]);

        React.useEffect(() => {
            try {
                window.__app_instrumentation = window.__app_instrumentation || {};
                window.__app_instrumentation.isRestoring = !!modals?.isRestoring;
                  console.info('[instrument] isRestoring', !!modals?.isRestoring);
            } catch {
                /* ignore */
            }
}, [modals?.isRestoring]);

        React.useEffect(() => {
            const check = () => {
                const shell = document.querySelector('.app-shell');
                if (shell) {
                    try {
                        document.documentElement.setAttribute('data-app-shell-mounted', 'true');
                    } catch { /* ignore error */ }
                    window.__app_instrumentation = window.__app_instrumentation || {};
                    window.__app_instrumentation.appShellMounted = true;
                      console.info('[instrument] app-shell-mounted');
                    return true;
                }
                return false;
            };
            if (check()) return;
            const obs = new MutationObserver(() => { if (check()) obs.disconnect(); });
            obs.observe(document.body, { childList: true, subtree: true });
            return () => obs.disconnect();
}, [user, modals?.isRestoring]);

        // Sincronizzazione immediata del tema (prevent flickering)
        React.useLayoutEffect(() => {
            if (themeState) {
                ThemeService.applyThemeState(themeState);
