        const leftPos = Math.min(window.innerWidth - 300, Math.max(16, rect.left - 100));
        style.left = `${leftPos}px`;
    }

    return (
        <div ref={popoverRef}  style={style}>
            <p >Assegna Badge</p>
            <div >
                {PARTICIPATION_BADGES.map(badge => (
                    <button 
