                                                                outcome?.action === "retain" ? "bg-error/10 text-error" : 
                                                                outcome?.action === "archive" || outcome?.action === "transfer" ? "bg-[var(--md-sys-color-surfaceContainerHigh)]est text-[var(--md-sys-color-onSurface)]-variant" : 
