import React, { useState } from 'react';
import { M3Dialog, M3DialogContent, M3DialogActions, M3Button } from './ui';

interface ShareModalProps {
    title: string;
    text: string;
    onClose: () => void;
}

const ShareModal: React.FC<ShareModalProps> = ({ title, text, onClose }) => {
    const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');

    const handleSimpleShare = async () => {
        if (navigator.share) {
            try {
                await navigator.share({
                    title: title,
                    text: text,
                });
                onClose();
            } catch (error) {
                console.error('Error sharing:', error);
            }
        } else {
            alert('La condivisione nativa non è supportata su questo browser.');
        }
    };

    const handleCopyFormatted = () => {
        const markdownText = text.split('\n').map(line => {
            const trimmed = line.trim();
            if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
                return trimmed;
            }
            return `- ${trimmed}`;
        }).join('\n');

        navigator.clipboard.writeText(markdownText).then(() => {
            setCopyStatus('copied');
            setTimeout(() => {
                setCopyStatus('idle');
                onClose();
            }, 1500);
        }).catch(err => {
            console.error('Failed to copy markdown text: ', err);
            alert('Impossibile copiare il testo formattato.');
        });
    };

    return (
        <M3Dialog
            onClose={onClose}
            title="Condividi"
            maxWidth="sm"
            level={1}
        >
            <M3DialogContent className="md3-share-modal-content">
                <p className="md3-share-description">Scegli come condividere il contenuto</p>
                
                <div className="md3-share-buttons">
                    <button onClick={handleSimpleShare} className="md3-share-button">
                        <div className="md3-share-icon md3-share-icon-secondary">
                            <span className="md3-share-icon-text">share</span>
                        </div>
                        <div>
                            <p className="md3-share-button-title">Condividi via...</p>
                            <p className="md3-share-button-subtitle">WhatsApp, Email, Drive</p>
                        </div>
                    </button>

                    <button onClick={handleCopyFormatted} className="md3-share-button">
                        <div className="md3-share-icon md3-share-icon-tertiary">
                            <span className="md3-share-icon-text">{copyStatus === 'copied' ? 'check' : 'content_paste'}</span>
                        </div>
                        <div>
                            <p className="md3-share-button-title">{copyStatus === 'copied' ? 'Copiato!' : 'Copia Formattato'}</p>
                            <p className="md3-share-button-subtitle">Per registro elettronico o Padlet</p>
                        </div>
                    </button>
                </div>
            </M3DialogContent>
            <M3DialogActions>
                <M3Button onClick={onClose} variant="text">Chiudi</M3Button>
            </M3DialogActions>
        </M3Dialog>
    );
};

