                            )}
                        </div>
                    </div>

                    <div >
                        {udaProp !== 'new' && (
                            <M3Button 
                                onClick={handleDelete} 
                                variant="text" 
                                
                            >
                                <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>delete</span>
