                        </M3DialogContent>
                        <M3DialogActions >
                            <M3Button onClick={handlePickerClose} variant="primary" style={{ width: "100%" }}>Conferma Selezione</M3Button>
                        </M3DialogActions>
                    </M3Dialog>
                )}
            </div>
        </div>
    );
};

